import java.util.*;

public class Main {
    public static void main(String[] a) {
        Scanner sc = new Scanner(System.in);
        int d = Integer.parseInt(sc.nextLine().trim());
        // 宣言順を保つ。列名 -> 書かれていた制約
        Map<String, Set<String>> columns = new LinkedHashMap<>();
        for (int i = 0; i < d; i++) {
            String line = sc.nextLine().trim();
            if (line.startsWith("CREATE TABLE") || line.startsWith(")")) continue;
            if (line.startsWith("CONSTRAINT")) {
                // 表全体の制約。CONSTRAINT ... FOREIGN KEY (customer_id) REFERENCES ...
                if (line.contains("FOREIGN KEY")) {
                    int open = line.indexOf('(', line.indexOf("FOREIGN KEY"));
                    String column = line.substring(open + 1, line.indexOf(')', open)).trim();
                    if (columns.containsKey(column)) columns.get(column).add("FOREIGN_KEY");
                }
                continue;
            }
            String name = line.split("\\s+")[0];
            Set<String> marks = new LinkedHashSet<>();
            if (line.contains("PRIMARY KEY")) marks.add("PRIMARY_KEY");
            if (line.contains("NOT NULL")) marks.add("NOT_NULL");
            if (line.contains("UNIQUE")) marks.add("UNIQUE");
            if (line.contains("CHECK")) marks.add("CHECK");
            if (line.contains("REFERENCES")) marks.add("FOREIGN_KEY");
            columns.put(name, marks);
        }
        List<String> order = List.of("PRIMARY_KEY", "NOT_NULL", "UNIQUE", "CHECK", "FOREIGN_KEY");
        for (Map.Entry<String, Set<String>> e : columns.entrySet()) {
            List<String> marks = new ArrayList<>();
            for (String mark : order) {
                if (e.getValue().contains(mark)) marks.add(mark);
            }
            System.out.println(e.getKey() + " " + (marks.isEmpty() ? "-" : String.join(",", marks)));
        }
    }
}

