import java.util.*;

public class Main {
    public static void main(String[] a) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.nextLine().trim());
        Set<String> checks = new TreeSet<>();
        for (int i = 0; i < n; i++) {
            String name = sc.nextLine().trim();
            String plan = sc.nextLine();
            long read = number(plan, "rows_read=");
            long returned = number(plan, "rows_returned=");
            boolean wasteful = returned == 0 ? read >= 1000 : read >= 1000 && read >= returned * 100;
            if (plan.contains("Seq Scan") && wasteful) checks.add(name);
        }
        if (checks.isEmpty()) {
            System.out.println("OK");
        } else {
            for (String name : checks) System.out.println("CHECK " + name);
        }
    }

    /** `rows_read=10000` のように key の直後へ続く数字を取り出す。 */
    static long number(String plan, String key) {
        int from = plan.indexOf(key) + key.length();
        int to = from;
        while (to < plan.length() && Character.isDigit(plan.charAt(to))) to++;
        return Long.parseLong(plan.substring(from, to));
    }
}

