import java.util.*;

public class Main {
    public static void main(String[] a) {
        Scanner sc = new Scanner(System.in);
        Map<String, String> applied = read(sc);
        Map<String, String> files = read(sc);

        Set<String> names = new TreeSet<>(Comparator.comparingInt(Main::version));
        names.addAll(applied.keySet());
        names.addAll(files.keySet());

        for (String name : names) {
            String history = applied.get(name);
            String onDisk = files.get(name);
            String state;
            if (history == null) state = "PENDING";
            else if (onDisk == null) state = "MISSING";
            else if (history.equals(onDisk)) state = "APPLIED";
            else state = "MODIFIED";
            System.out.println(state + " " + name);
        }
    }

    static Map<String, String> read(Scanner sc) {
        int count = Integer.parseInt(sc.nextLine().trim());
        Map<String, String> map = new HashMap<>();
        for (int i = 0; i < count; i++) {
            String[] parts = sc.nextLine().trim().split("\\s+");
            map.put(parts[0], parts[1]);
        }
        return map;
    }

    /** `V10__add_index.sql` から 10 を取り出す。V10はV9より後なので数として比べる。 */
    static int version(String name) {
        return Integer.parseInt(name.substring(1, name.indexOf("__")));
    }
}

