import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int c = sc.nextInt();
        Map<Long, String> names = new LinkedHashMap<>();
        for (int i = 0; i < c; i++) {
            long id = sc.nextLong();
            names.put(id, sc.next());
        }
        int n = sc.nextInt();
        Map<Long, Long> paid = new HashMap<>();
        for (int i = 0; i < n; i++) {
            long customerId = sc.nextLong();
            String status = sc.next();
            long total = sc.nextLong();
            if (status.equals("PAID")) paid.merge(customerId, total, Long::sum);
        }
        long threshold = sc.nextLong();
        List<Map.Entry<String, Long>> rows = new ArrayList<>();
        for (Map.Entry<Long, String> e : names.entrySet()) {
            long sum = paid.getOrDefault(e.getKey(), 0L);
            if (sum >= threshold) rows.add(Map.entry(e.getValue(), sum));
        }
        rows.sort(Comparator.comparingLong((Map.Entry<String, Long> r) -> r.getValue()).reversed().thenComparing(Map.Entry::getKey));
        if (rows.isEmpty()) System.out.println("NONE");
        else for (Map.Entry<String, Long> r : rows) System.out.println(r.getKey() + "=" + r.getValue());
    }
}

