import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int m = sc.nextInt();
        List<List<Integer>> txs = new ArrayList<>();
        for (int i = 0; i < m; i++) {
            int k = sc.nextInt();
            List<Integer> ids = new ArrayList<>();
            for (int j = 0; j < k; j++) ids.add(sc.nextInt());
            txs.add(ids);
        }
        for (int i = 0; i < m; i++) {
            List<Integer> ids = txs.get(i);
            boolean sorted = true;
            for (int j = 1; j < ids.size(); j++) if (ids.get(j) < ids.get(j - 1)) sorted = false;
            System.out.println("T" + (i + 1) + (sorted ? " OK" : " REORDER"));
        }
        boolean risk = false;
        for (int i = 0; i < m && !risk; i++) for (int j = i + 1; j < m && !risk; j++) {
            List<Integer> x = txs.get(i), y = txs.get(j);
            for (int p = 0; p < x.size() && !risk; p++) for (int q = p + 1; q < x.size() && !risk; q++) {
                int pa = y.indexOf(x.get(p)), pb = y.indexOf(x.get(q));
                if (pa >= 0 && pb >= 0 && pa > pb) risk = true;
            }
        }
        System.out.println(risk ? "RISK" : "SAFE");
    }
}
